-- 由顺序配置派生当前等级 -> 配置的 KV，业务判断不直接依赖数组位置。
local levelConfig = {}
for _, config in ipairs(dengjitupo.data) do levelConfig[config[1]] = config end

local levelRangeMap = {}
for _, range in ipairs(levelRange) do levelRangeMap[range[1]] = range end


local function getlevel(player)
    return getbaseinfo(player, 6) + ws.GetAtt(player, 255)
end

-- 打开等级突破界面；先按全功能等级范围过滤，再按当前大陆校验对应突破区间。
function dengjitupo.main(player, npcId, npcName)
    local level = getlevel(player)
    local minLevel = levelRange[1][2]
    local maxLevel = levelRange[#levelRange][3]
    if level < minLevel then
        ws.msg(player, string.format("等级突破需达到%d级后开启，请先提升到%d级后再来！", minLevel, minLevel))
        return
    end
    if level >= maxLevel then
        ws.msg(player, string.format("当前等级已达到等级突破最高等级%d级！", maxLevel))
        return
    end

    local range = levelRangeMap[ws.GetInt(player, "大陆等级")]
    if not range then
        ws.msg(player, "等级突破当前仅支持3-8大陆，请前往对应大陆后再来！")
        return
    end
    if level < range[2] then
        ws.msg(player, string.format("当前大陆等级突破需达到%d级，请先提升到%d级后再来！", range[2], range[2]))
        return
    end
    if level >= range[3] then
        ws.msg(player, string.format("当前大陆等级突破上限为%d级，请前往下一大陆继续突破！", range[3]))
        return
    end

    ws.ShowForm(player, "form/"..scriptName, level, range[3])
end

-- 按全功能等级范围和当前大陆突破区间复核，定位配置并在扣除成功后提升 1 级。
function dengjitupo.start(player)
    local level = getlevel(player)
    local minLevel = levelRange[1][2]
    local maxLevel = levelRange[#levelRange][3]
    if level < minLevel then
        ws.msg(player, string.format("等级突破需达到%d级后开启，请先提升到%d级后再来！", minLevel, minLevel))
        return
    end
    if level >= maxLevel then
        ws.msg(player, string.format("当前等级已达到等级突破最高等级%d级！", maxLevel))
        return
    end

    local range = levelRangeMap[ws.GetInt(player, "大陆等级")]
    if not range then
        ws.msg(player, "等级突破当前仅支持3-8大陆，请前往对应大陆后再来！")
        return
    end
    if level < range[2] then
        ws.msg(player, string.format("当前大陆等级突破需达到%d级，请先提升到%d级后再来！", range[2], range[2]))
        return
    end
    if level >= range[3] then
        ws.msg(player, string.format("当前大陆等级突破上限为%d级，请前往下一大陆继续突破！", range[3]))
        return
    end

    local config = levelConfig[level]
    if not config then
        ws.msg(player, "当前等级突破配置不存在，请联系客服！")
        return
    end

    local result = ws.SubUseMode(player, config[3], config[2], "等级突破")
    if result ~= "true" then
        ws.msg(player, result)
        return
    end

    changelevel(player, "=", level + 1)
    ws.SetInt(player, "等级突破等级", ws.GetInt(player, "等级突破等级") + 1)
    dengjitupo.update(player)
    ws.ShowFormFunc(player, "dengjitupo_effect", 1)
end

-- 将服务端确认后的真实人物等级和当前大陆突破上限刷新给已打开页面。
function dengjitupo.update(player)
    local range = levelRangeMap[ws.GetInt(player, "大陆等级")]
    ws.ShowFormFunc(player, "dengjitupo_update", getlevel(player), range and range[3] or 0)
end
